    $q=new SqlCoordinator($db,$prefix,2);$q->migrate();$q->migrate();$now=$q->clock();check(abs(time()-$now)<5);rejects(fn()=>$db->transaction(fn()=>$q->dispatch('task',[],true,$now)));rejects(fn()=>$q->dispatch('unsafe',[],false,$now));$id=$q->dispatch('test',[],true,$now);$first=$q->claim($now,10);check($first->id===$id&&$q->claim($now,10)===null);$second=$q->claim($now+11,10);check($second->attempt===2&&!$q->complete($first,[],$now+11)&&!$q->renew($first,$now+11));check($q->renew($second,$now+12,20)&&$q->complete($second,['ok'=>true],$now+13));check(!str_contains(json_encode($first),$first->token()));
    $id=$q->dispatch('retry',[],true,$now);$retry=$q->claim($now,10);check($q->fail($retry,$now)&&$q->claim($now)===null);$retry=$q->claim($now+6,10);check($retry->attempt===2&&$q->fail($retry,$now+6));check($q->status()['dead']===1);
    $lease=$q->acquire('singleton-scheduler',$now,10);check($lease!==null&&$q->acquire('singleton-scheduler',$now,10)===null);$new=$q->acquire('singleton-scheduler',$now+11,10);check($new->fence===$lease->fence+1&&!$q->release($lease,$now+11)&&$q->release($new,$now+12));$next=$q->acquire('singleton-scheduler',$now+13,10);check($next->fence===$new->fence+1);
    $scopes=new ScopeManager();$closed=false;$q->dispatch('cleanup',[],true,$now);$worker=new JobWorker($q,$scopes,['cleanup'=>static function(array $input,$claim,$scope)use(&$closed):array{$scope->onClose(static function()use(&$closed):void{$closed=true;});throw new \RuntimeException('private error must not persist');}]);check($worker->once()['status']==='failed'&&$closed&&$scopes->activeCount()===0);$q->dispatch('unknown',[],true,$now);check((new JobWorker($q,$scopes,[]))->once()['status']==='unknown_task');
    if(function_exists('openssl_encrypt')){$transport=new class implements MailTransport{public int $sent=0;public function send(string $id,AccountMessage $message):void{$this->sent++;}};$mailQueue=new SqlCoordinator($db,$prefix.'m');$mail=new SqlMailQueue($mailQueue,new SecretBox(random_bytes(32)),$transport);$mail->migrate();$mail->deliver(new AccountMessage('private@example.test','reset',$now+600,'https://example.test/reset#token=private-token'));$rows=$db->select('SELECT input FROM '.$db->quoteIdentifier($prefix.'m_jobs'));check(!str_contains($rows[0]['input'],'private@example.test')&&!str_contains($rows[0]['input'],'private-token'));check($mail->workOnce()['status']==='completed'&&$transport->sent===1);}
}
